"""Writes obsidian/catalog.json. Local only."""
import json
M = "Verified on macOS 15.6.1 with Obsidian 1.9.14 (whose installed update ran as 1.12.7) only, so it isn't known to work on macOS 26 or any other version."
ROOT = "Only touches what OBSIDIAN_ALLOWED_ROOT allows if it is set; if it isn't set, any folder you can reach is accepted."
EN = "It depends on English names and was tested only in English."
UIM = {"name": "mode", "type": "str", "required": False, "default": "ui", "meaning": "Must be \"ui\": there is no background mode."}
VAULT = {"name": "vault", "type": "str", "required": True, "default": None, "meaning": "The vault's folder, an absolute path or one starting with ~."}
V = {"name": "ValueError", "when": "an argument is invalid or mode isn't \"ui\" or \"background\""}
