PRE = "The program has Accessibility, and Automation for System Events. Obsidian is asked to show its window to Accessibility."
def cmd(name, desc, args, req, eff, post, ret, errs, gaps):
    return {"name": name, "description": desc, "args": args, "modes": {"verified": ["ui"], "default": "ui"}, "example_requests": req, "effects": eff, "destructive": False, "precondition": PRE, "postcondition": post, "returns": ret, "errors": errs, "known_gaps": gaps}
cmds = [
 cmd("vault_create", "Makes a new vault in a folder with Create local vault in Obsidian's vault picker, and Obsidian opens it.", [{"name": "name", "type": "str", "required": True, "default": None, "meaning": "The vault's name, which is also its folder's name."}, {"name": "folder", "type": "str", "required": True, "default": None, "meaning": "The folder to make it in, which must exist."}, UIM], ["Make a new Obsidian vault called Research", "Create a vault in my Documents folder", "Start a new notes vault"], "non_idempotent", "The vault's folder exists with Obsidian's settings in it, and Obsidian knows it.", {"type": "object", "fields": ["name", "path"]}, [V, U, S, {"name": "NotFound", "when": "the folder doesn't exist; nothing is made"}, {"name": "AlreadyExists", "when": "something already has that name in the folder; nothing is made"}, OUT, NS], [M, ROOT, EN, "Obsidian adds its own Welcome note to a new vault.", "Sync and signing in weren't used."]),
 cmd("vault_list", "Lists the vaults Obsidian knows, from its own registry file.", [UIM], ["Which Obsidian vaults do I have?", "List my vaults", "Where are my Obsidian vaults?"], "read_only", "Nothing is changed.", {"type": "list", "fields": ["name", "path"]}, [V, {"name": "UIError", "when": "never raised by this command; listed for a consistent error set"}, NS], [M, "It reads Obsidian's registry file, so it works with Obsidian closed."]),
 cmd("note_create", "Makes a note in a vault with Obsidian's own obsidian://new link; links such as [[Other note]] are kept as written.", [VAULT, {"name": "title", "type": "str", "required": True, "default": None, "meaning": "The note's title, which is also its file name; one line without /."}, {"name": "text", "type": "str", "required": False, "default": "", "meaning": "The note's text, in Markdown."}, UIM], ["Make a note called Ideas in my vault", "Add a note that links to Project Plan", "Write this down as a new Obsidian note"], "non_idempotent", "The vault has title.md holding exactly the text.", {"type": "object", "fields": ["vault", "title", "path"]}, [V, U, S, NFV, {"name": "AlreadyExists", "when": "a note with that title exists; nothing is changed"}, OUT, NS], [M, ROOT, "It opens the note in Obsidian.", "Notes in subfolders weren't tested."]),
 cmd("note_open", "Opens a note in its vault's Obsidian window with Obsidian's own obsidian://open link.", [VAULT, {"name": "note", "type": "str", "required": True, "default": None, "meaning": "The note's path inside the vault without .md, such as Ideas or Projects/Plan."}, UIM], ["Open my Ideas note in Obsidian", "Show the Project Plan note", "Open Links.md in ResearchVault"], "idempotent", "The vault's window shows the note; no note file changes.", {"type": "object", "fields": ["vault", "note", "path"]}, [V, U, S, {"name": "NotFound", "when": "Obsidian doesn't know a vault at that folder, or the note doesn't exist in it; nothing is changed"}, OUT, NS], [M, ROOT, "Obsidian writes its own workspace state in the vault's .obsidian folder.", "Added overnight in its own section and tested on its own."]),
 cmd("plugin_install", "Installs a community plugin from Obsidian's directory into a vault and turns it on (the plugin's page through obsidian://show-plugin, Install, Enable); a vault in Restricted mode is taken out of it first.",
     [{"name": "vault", "type": "str", "required": True, "default": None, "meaning": "The vault's folder, absolute or starting with ~."}, {"name": "plugin_id", "type": "str", "required": True, "default": None, "meaning": "The plugin's id in Obsidian's community directory, such as obsidian-excalidraw-plugin."}, UIM],
     ["Install the Excalidraw plugin in my vault", "Add the Kanban plugin", "Turn on the Dataview plugin in ResearchVault"], "non_idempotent", "The plugin is installed and listed as on in the vault's community-plugins.json.", {"type": "object", "fields": ["vault", "plugin", "enabled"]},
     [V, U, S, NFV, {"name": "AlreadyExists", "when": "the plugin is already installed and on; nothing is changed"}, OUT, NS],
     [M, ROOT, EN, "It needs the internet.", "It turns off the vault's Restricted mode (Obsidian's Turn on community plugins) if it's on, which lets community plugins run in that vault.", "Obsidian updates its own app code while it runs, so the version a vault shows can change.", "Added on day 4 in its own section and tested on its own."]),
]
json.dump({"app": "Obsidian", "import": "import obsidian", "macos_version": "15.6.1 (24G90)", "app_version": "1.9.14 (0.14.8)", "commands": cmds}, open("../obsidian/catalog.json", "w"), indent=2, ensure_ascii=False); open("../obsidian/catalog.json", "a").write("\n"); print(len(cmds))
